#!/usr/bin/env python3
"""Source of _build/guides_i18n/stems.json (localized /vocal-remover/ pages).

    python3 _build/guides_i18n/stems_src.py && python3 _build/add_local_guides.py stems && python3 _build/set_sampler_hero.py stems

App labels (Studio, STEMS, Original, Vocal, Instrumental, Stems ready) stay in English
because the app is in English. Stems is iPhone only for now. {key} is the language's
change-key page.
"""
import json
from pathlib import Path


def page(slug, title, desc, eyebrow, h1, h1sub, lede, alt, statement, features_title, features,
         steps_h, steps, good_h, good, uses_h, uses, price, rights, also, faq_title, faq, cta, note):
    prose = (f'<h2>{steps_h}</h2><ol>' + ''.join(f'<li>{s}</li>' for s in steps) + '</ol>'
             f'<h2>{good_h}</h2><ul>' + ''.join(f'<li><strong>{a}</strong> {b}</li>' for a, b in good) + '</ul>'
             f'<h2>{uses_h}</h2><ul>' + ''.join(f'<li><strong>{a}</strong> {b}</li>' for a, b in uses) + '</ul>'
             f'<p>{price}</p><p>{rights}</p><p>{also}</p>')
    return dict(slug=slug, title=title, desc=desc, crumb='VibeDeck Stems', eyebrow=eyebrow, h1=h1, h1sub=h1sub,
                lede=lede, alt=alt, statement=statement, features_title=features_title, features=features,
                prose=prose, faq_title=faq_title, faq=faq, cta=cta, note=note)


